export async function setProjectReviewState(id: string, state: ReviewState): Promise<void> {
  await db.understandingProjects.update(id, { reviewState: state, updatedAt: new Date() });
}

/**
 * Delete a project and every record scoped to it: associations, understanding
 * objects (with their events and intent/decision traces), prepared changes,
 * question-first investigation cases (with exhibits, scopes, verdicts and
 * findings), and the local-only inspection log and decision diffs.
 *
 * Conversations and messages are NEVER touched. A project is a lens over
 * imported history, not its owner — the same conversation can back several
 * projects, and removing the lens must not remove the primary sources
 * (mirrors deleteConversation, which drops associations but keeps synthesis).
 *
 * Per-row deletes (not table clears) so the sync engine's `deleting` hooks
 * emit a tombstone for each synced row. Safe to call for an id that no longer
 * exists — the engine reuses this to apply an incoming project tombstone.
 */
export async function deleteUnderstandingProject(id: string): Promise<void> {
  await db.transaction(
    'rw',
    [
      db.understandingProjects,
      db.projectAssociations,
      db.understandingObjects,
      db.understandingEvents,
      db.intentTraces,
      db.decisionTraces,
      db.decisionDiffs,
      db.preparedChanges,
      db.investigationCases,
      db.caseExhibits,
      db.reviewScopes,
      db.verdictRevisions,
      db.investigationFindings,
      db.inspections,
    ],
    async () => {
      const objectIds = await db.understandingObjects.where('projectId').equals(id).primaryKeys();
      const caseIds = await db.investigationCases.where('projectId').equals(id).primaryKeys();

      await db.understandingProjects.delete(id);
      await db.projectAssociations.where('projectId').equals(id).delete();

      await db.understandingObjects.where('projectId').equals(id).delete();
      if (objectIds.length > 0) {
        await db.understandingEvents.where('objectId').anyOf(objectIds).delete();
      }
      await db.intentTraces.where('projectId').equals(id).delete();
      await db.decisionTraces.where('projectId').equals(id).delete();
      await db.decisionDiffs.where('projectId').equals(id).delete();

      await db.preparedChanges.where('projectId').equals(id).delete();

      await db.investigationCases.where('projectId').equals(id).delete();
      if (caseIds.length > 0) {
        await db.caseExhibits.where('caseId').anyOf(caseIds).delete();
        await db.reviewScopes.where('caseId').anyOf(caseIds).delete();
        await db.verdictRevisions.where('caseId').anyOf(caseIds).delete();
      }
      await db.investigationFindings.where('projectId').equals(id).delete();

      await db.inspections.where('projectId').equals(id).delete();
    }
  );
}

case 'understanding_project':
  // Mirror the local cascade so project-scoped rows (and the
  // local-only inspections/decisionDiffs, which never get their own
  // tombstones) do not dangle. Conversations are deliberately kept.
  await deleteUnderstandingProject(rec.id);
  return;

