    const { seedSampleWorkspace, SAMPLE_PROJECT_ID } = await import('../demo/seedWorkspace');
    const { projectId } = await seedSampleWorkspace();
    expect(projectId).toBe(SAMPLE_PROJECT_ID);
    await seedProjectScopedRows(projectId);

    // Sanity: the fixture populated every table the cascade touches.
    const conversationCount = await db.conversations.count();
    const messageCount = await db.messages.count();
    const rawSourceCount = await db.rawSources.count();
    expect(conversationCount).toBeGreaterThan(0);
    expect(messageCount).toBeGreaterThan(0);
    const caseIds = await db.investigationCases.where('projectId').equals(projectId).primaryKeys();
    expect(caseIds.length).toBeGreaterThan(0);
    for (const table of [
      db.projectAssociations,
      db.understandingObjects,
      db.preparedChanges,
      db.investigationFindings,
      db.intentTraces,
      db.decisionTraces,
      db.decisionDiffs,
      db.inspections,
    ]) {
      expect(await table.where('projectId').equals(projectId).count()).toBeGreaterThan(0);
