    expect(await db.caseExhibits.where('caseId').anyOf(caseIds).count()).toBeGreaterThan(0);
    expect(await db.reviewScopes.where('caseId').anyOf(caseIds).count()).toBeGreaterThan(0);
    expect(await db.understandingEvents.count()).toBeGreaterThan(0);

    await deleteUnderstandingProject(projectId);

    expect(await getUnderstandingProject(projectId)).toBeUndefined();
    for (const table of [
      db.projectAssociations,
      db.understandingObjects,
      db.preparedChanges,
      db.investigationCases,
      db.investigationFindings,
      db.intentTraces,
      db.decisionTraces,
      db.decisionDiffs,
      db.inspections,
    ]) {
      expect(await table.where('projectId').equals(projectId).count()).toBe(0);
    }
    expect(await db.caseExhibits.where('caseId').anyOf(caseIds).count()).toBe(0);
    expect(await db.reviewScopes.where('caseId').anyOf(caseIds).count()).toBe(0);
    expect(await db.verdictRevisions.where('caseId').anyOf(caseIds).count()).toBe(0);
    expect(await db.understandingEvents.count()).toBe(0);

    // The primary sources survive untouched.
    expect(await db.conversations.count()).toBe(conversationCount);
    expect(await db.messages.count()).toBe(messageCount);
    expect(await db.rawSources.count()).toBe(rawSourceCount);
  });

  it('leaves other projects and their rows alone', async () => {
    const keep = await createHumanProject({ name: 'Keep' });
    const drop = await createHumanProject({ name: 'Drop' });
    await db.conversations.put({
      id: 'shared-conv',
      source: 'claude-ai',
      name: 'Shared',
