      fullText: '',
    });
    await associateConversationWithProject(keep.id, 'shared-conv');
    await associateConversationWithProject(drop.id, 'shared-conv');
    const keepObject = await seedProjectScopedRows(keep.id);
    await seedProjectScopedRows(drop.id);

    await deleteUnderstandingProject(drop.id);

    expect(await getUnderstandingProject(drop.id)).toBeUndefined();
    expect(await getUnderstandingProject(keep.id)).toBeDefined();
    expect(await db.conversations.get('shared-conv')).toBeDefined();
    expect(await getAssociationsForProject(keep.id)).toHaveLength(1);
    expect(await getAssociationsForProject(drop.id)).toHaveLength(0);
    expect(await getUnderstandingObject(keepObject.id)).toBeDefined();
    expect(await getEventsForObject(keepObject.id)).toHaveLength(1);
    for (const table of [db.intentTraces, db.decisionTraces, db.decisionDiffs, db.inspections]) {
      expect(await table.where('projectId').equals(keep.id).count()).toBe(1);
      expect(await table.where('projectId').equals(drop.id).count()).toBe(0);
    }
  });

  it('is a no-op for an unknown id', async () => {
    const keep = await createHumanProject({ name: 'Keep' });
    await expect(deleteUnderstandingProject('missing')).resolves.toBeUndefined();
    expect(await getUnderstandingProject(keep.id)).toBeDefined();
  });
});
