import { beforeEach, describe, expect, it } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter, Route, Routes } from 'react-router-dom';
import { db } from '../lib/db/schema';
import { bulkPutConversations, bulkPutMessages, clearAllData } from '../lib/db';
import {
  associateConversationWithProject,
  createHumanProject,
  createUnderstandingObject,
  getUnderstandingProject,
} from '../lib/db/understanding';
import { ProjectOverviewPage } from './ProjectOverviewPage';

const now = new Date('2026-09-07T12:00:00Z');

async function seed() {
  const project = await createHumanProject({ name: 'Doomed project' });
  await bulkPutConversations([
    {
      id: 'conv-1',
      source: 'claude-code',
      name: 'Kept conversation',
      summary: null,
      createdAt: now,
      updatedAt: now,
      importedAt: now,
      messageCount: 1,
      userMessageCount: 1,
      assistantMessageCount: 0,
      estimatedTokens: 5,
      fullText: '',
    },
  ]);
  await bulkPutMessages([
    { id: 'm-1', conversationId: 'conv-1', sender: 'user', text: 'hello', createdAt: now },
  ]);
  await associateConversationWithProject(project.id, 'conv-1');
  await createUnderstandingObject({
    projectId: project.id,
    type: 'belief',
    title: 'A belief',
    origin: 'user',
    evidence: [],
    occurredAt: now,
  });
  return project;
}

function renderAt(path: string) {
  return render(
    <MemoryRouter
      future={{ v7_startTransition: true, v7_relativeSplatPath: true }}
      initialEntries={[path]}
    >
      <Routes>
        <Route path="/projects" element={<p>Projects index</p>} />
        <Route path="/projects/:id" element={<ProjectOverviewPage />} />
      </Routes>
    </MemoryRouter>
  );
}

beforeEach(async () => {
  await clearAllData();
  localStorage.clear();
});

describe('ProjectOverviewPage — delete project', () => {
  it('asks for confirmation, then deletes the project but keeps its conversations', async () => {
    const user = userEvent.setup();
    const project = await seed();
    localStorage.setItem('chatdex.lastProjectId', project.id);
    localStorage.setItem('chatdex.lastProjectSection', 'overview');
    renderAt(`/projects/${project.id}`);

    expect(await screen.findByRole('heading', { level: 1, name: 'Doomed project' })).toBeInTheDocument();
    expect(screen.getByText(/Conversations are never deleted/)).toBeInTheDocument();
    expect(screen.queryByRole('alertdialog')).not.toBeInTheDocument();

    // Nothing is deleted by the first click.
    await user.click(screen.getByRole('button', { name: 'Delete project…' }));
    const dialog = await screen.findByRole('alertdialog');
    expect(dialog).toHaveTextContent('Permanently delete “Doomed project”?');
    expect(dialog).toHaveTextContent('Conversations are not deleted.');
    expect(await getUnderstandingProject(project.id)).toBeDefined();

    // Cancel backs out without side effects.
    await user.click(screen.getByRole('button', { name: 'Cancel' }));
    expect(screen.queryByRole('alertdialog')).not.toBeInTheDocument();
    expect(await getUnderstandingProject(project.id)).toBeDefined();

    await user.click(screen.getByRole('button', { name: 'Delete project…' }));
    await user.click(screen.getByRole('button', { name: 'Delete permanently' }));

    expect(await screen.findByText('Projects index')).toBeInTheDocument();
    await waitFor(async () => {
      expect(await getUnderstandingProject(project.id)).toBeUndefined();
    });
    expect(await db.projectAssociations.where('projectId').equals(project.id).count()).toBe(0);
    expect(await db.understandingObjects.where('projectId').equals(project.id).count()).toBe(0);
    expect(await db.conversations.get('conv-1')).toBeDefined();
    expect(await db.messages.where('conversationId').equals('conv-1').count()).toBe(1);
    expect(localStorage.getItem('chatdex.lastProjectId')).toBeNull();
    expect(localStorage.getItem('chatdex.lastProjectSection')).toBeNull();
  });
});

